#include <stdio.h>
#include <string.h>
#include <stdbool.h>

int main(int argc, char *argv[]) {
    if (argc < 3) {
        puts("USAGE");
        return 0;
    }
    const char *s1 = argv[1];
    const char *s2 = argv[2];
    /* Length limit: 1024 characters (0x400). The original checks < 0x401 (1025).
       If either string is too long, print TOO_LONG. */
    if (strlen(s1) >= 0x401 || strlen(s2) >= 0x401) {
        puts("TOO_LONG");
        return 0;
    }
    int cnt1[256] = {0};
    int cnt2[256] = {0};
    /* Count characters of first string, ignoring spaces, case‑insensitive for A‑Z */
    for (size_t i = 0; s1[i] != '\0'; ++i) {
        unsigned char c = (unsigned char)s1[i];
        if (c == ' ') continue;               // ignore spaces
        if (c >= 'A' && c <= 'Z') c += 32;    // to lower case
        cnt1[c]++;
    }
    /* Same for second string */
    for (size_t i = 0; s2[i] != '\0'; ++i) {
        unsigned char c = (unsigned char)s2[i];
        if (c == ' ') continue;
        if (c >= 'A' && c <= 'Z') c += 32;
        cnt2[c]++;
    }
    bool anagram = true;
    for (int i = 0; i < 256; ++i) {
        if (cnt1[i] != cnt2[i]) { anagram = false; break; }
    }
    puts(anagram ? "ANAGRAM" : "NOT_ANAGRAM");
    return 0;
}
